		'DataSources.URLReference': {
			type: 'string',
			description:
				'A reference to a HTTP or HTTPS URL.\n\nThe URLs are parsed using the WHATWG URL standard, which means they can optionally contain usernames and passwords if needed.',
			pattern: '^https?://\\S+$',
		},
		'DataSources.ExecutionContextPath': {
			type: 'string',
			description:
				'A reference to a file in the Blueprint Execution Context – see the main proposal document for more context.\n\nThe path must start with either ./ or / to distinguish it from a plugin or theme slug. Regardless of the prefix (./ or /), the path is relative to the Blueprint Execution Context root:\n\n* Relative paths (./) are relative to the location of blueprint.json file.\n* Absolute paths (/) are chrooted at the Blueprint Execution Context root which is   still the directory where blueprint.json is located.\n\nIt is not possible to escape the Blueprint Execution Context via "../" sequences.',
			pattern: '^(?:\\./|/)(?!.*(?:^|[/\\\\]|:)\\.\\.(?:[/\\\\]|$)).*$',
		},
		'DataSources.WordPressVersion': {
			description:
				'WordPress version, e.g. "6.4", "6.4.3", "6.8-RC1", or "6.7-beta2".\n\nThese refer to slugs of specific WordPress releases as listed in the first table column on https://wordpress.org/download/releases/.\n\nThe WordPressVersion type is only meaningful in the top-level `wordpressVersion` property.',
			type: 'string',
			pattern:
				'^(?:latest|\\d+\\.\\d+(?:\\.\\d+)?(?:-(?:beta\\d+|[Rr][Cc]\\d+))?)$',
		},
		'DataSources.SimpleVersionExpression': {
			type: 'string',
			pattern: '^(?:latest|\\d+\\.\\d+(?:\\.\\d+)?)$',
		},
